/// <summary>
/// Provides properties for inventory instrumentation logging.
/// </summary>
final internal class METInventInstrumentationLoggerProperties extends SysInstrumentationLoggerAppSuiteProperties
{
    internal readonly str InventUpdateClassName = 'ClassName';
    internal readonly str InventUpdateMovementClass = 'MovementClass';
    internal readonly str InventTransOriginStart = 'TransOriginStart';
    internal readonly str InventTransOriginStop = 'TransOriginStop';
    internal readonly str InventUpdateOnhandContext = 'Context';

    internal readonly str WhsItem = 'WhsItem';
    internal readonly str CwItem = 'CwItem';
    internal readonly str StockedItem = 'StockedItem';
    internal readonly str BatchItem = 'BatchItem';
    internal readonly str SerialItem = 'SerialItem';
    internal readonly str OwnerItem = 'OwnerItem';
    internal readonly str VariantItem = 'VariantItem';
    internal readonly str InventTransId = 'InventTransId';
    internal readonly str InventTransOriginId = 'InventTransOriginId';

}

Method.Source:
/// <summary>
/// new constructor for METInventInstrumentationLoggerProperties.
/// </summary>
private void new()
{
}

/// <summary>
/// whsItem property for InventMovement.
/// </summary>
/// <param name = "_movement">InventMovement</param>
/// <returns>METSysInstrumentationLoggerAppSuiteProperty</returns>
final internal METSysInstrumentationLoggerAppSuiteProperty isWHSItem(InventMovement _movement)
{
    return METSysInstrumentationLoggerAppSuiteProperty::newProperty(this.WhsItem, int2Str(_movement.isItemWHSEnabled()));
}

/// <summary>
/// cwItem property for InventMovement.
/// </summary>
/// <param name = "_movement">InventMovement</param>
/// <returns>METSysInstrumentationLoggerAppSuiteProperty</returns>
final internal METSysInstrumentationLoggerAppSuiteProperty isCwItem(InventMovement _movement)
{
    return METSysInstrumentationLoggerAppSuiteProperty::newProperty(this.CwItem, int2Str(_movement.pdsCWItem()));
}

/// <summary>
/// stockedItem property for InventMovement.
/// </summary>
/// <param name = "_movement">InventMovement</param>
/// <returns>METSysInstrumentationLoggerAppSuiteProperty</returns>
final internal METSysInstrumentationLoggerAppSuiteProperty isStockedItem(InventTable _inventTable)
{
    return METSysInstrumentationLoggerAppSuiteProperty::newProperty(this.StockedItem, int2Str(_inventTable.isStocked()));
}

/// <summary>
/// batchItem property for InventMovement.
/// </summary>
/// <param name = "_movement">InventMovement</param>
/// <returns>METSysInstrumentationLoggerAppSuiteProperty</returns>
final internal METSysInstrumentationLoggerAppSuiteProperty isBatchItem(InventDimParm _physicalDimensions)
{
    return METSysInstrumentationLoggerAppSuiteProperty::newProperty(this.BatchItem, int2Str(_physicalDimensions.InventBatchIdFlag == NoYes::Yes));
}

/// <summary>
/// serialItem property for InventMovement.
/// </summary>
/// <param name = "_movement">InventMovement</param>
/// <returns>METSysInstrumentationLoggerAppSuiteProperty</returns>
final internal METSysInstrumentationLoggerAppSuiteProperty isSerialItem(InventDimParm _physicalDimensions)
{
    return METSysInstrumentationLoggerAppSuiteProperty::newProperty(this.SerialItem, int2Str(_physicalDimensions.InventSerialIdFlag == NoYes::Yes));
}

/// <summary>
/// ownerItem property for InventMovement.
/// </summary>
/// <param name = "_movement">InventMovement</param>
/// <returns>METSysInstrumentationLoggerAppSuiteProperty</returns>
final internal METSysInstrumentationLoggerAppSuiteProperty isOwnerItem(InventDimParm _physicalDimensions)
{
    return METSysInstrumentationLoggerAppSuiteProperty::newProperty(this.OwnerItem, int2Str(_physicalDimensions.InventOwnerIdFlag_RU == NoYes::Yes));
}

/// <summary>
/// is variant item property for InventMovement.
/// </summary>
/// <param name = "_movement">InventMovement</param>
/// <returns>METSysInstrumentationLoggerAppSuiteProperty</returns>
final internal METSysInstrumentationLoggerAppSuiteProperty isVariantItem(InventDimParm _productDimensions)
{
    return METSysInstrumentationLoggerAppSuiteProperty::newProperty(this.VariantItem, int2Str(_productDimensions.anyProductDimensionFlagSet()));
}

/// <summary>
/// /// whsItem property for InventMovement.
/// </summary>
/// <returns>METInventInstrumentationLoggerProperties</returns>
internal static METInventInstrumentationLoggerProperties construct()
{
    return new METInventInstrumentationLoggerProperties();
}
